// Native 0x1426dedd0 (fully read). Authority-only attach setup. Offsets are the decompile offsets; names proposed.
if (Role != ROLE_Authority || AttachToActor == nullptr) { return; }
USceneComponent* Root = RootComp;                          // this+0x638
UProjectileMovementComponent* Movement = MovementComp;     // this+0x640
if (Root == nullptr || Movement == nullptr) { return; }

const FVector Velocity = Movement->Velocity;               // +0xc4 / +0xc8 / +0xcc
const FVector Step = Velocity * 0.033f;                    // fixed 0.033 s lookahead
const FVector RootLoc = Root->ComponentLocation;           // +0x1d0 / +0x1d4 / +0x1d8
const FVector SegStart = RootLoc - Step;
const FVector SegEnd = RootLoc + Step;

// Target location: AttachToActor's root component location (+0x130 -> +0x1d0), or the zero vector.
USceneComponent* TargetRoot = AttachToActor->RootComponent;
const FVector TargetLoc = (TargetRoot != nullptr) ? TargetRoot->ComponentLocation : FVector::ZeroVector;

// Closest point on the velocity segment to the target (helper 0x142c4b210, clamped projection).
FVector Closest = FMath::ClosestPointOnSegment(TargetLoc, SegStart, SegEnd);

// Normalised velocity direction (rsqrt with two Newton steps, only if |V|^2 > 1e-8).
FVector Dir = Velocity;
const float LenSq = Dir.X * Dir.X + Dir.Y * Dir.Y + Dir.Z * Dir.Z;
if (LenSq > 1e-8f)
{
    const float InvLen = 1.0f / FMath::Sqrt(LenSq);       // decompile: rsqrtss + 2 Newton iterations
    Dir = Dir * InvLen;
}

// Sticky pull along Dir when the target is a FortPawn with a bounds component at +0x288.
if (AttachToActor->IsA(AFortPawn::StaticClass()) && AttachToActor->BoundsComponent != nullptr)   // +0x288
{
    UPawnBounds* Bounds = AttachToActor->BoundsComponent;
    const float Extent = FMath::Min(Bounds->ExtentA, Bounds->ExtentB) * Bounds->ScaleFactor * -0.25f;   // +0x1e0, +0x1e4, +0x404
    Closest = Closest + Dir * Extent;
}

AttachedActor = AttachToActor;                              // this+0x8f8
AttachHitResult = Hit;                                      // this+0x868, 0x88-byte FHitResult copy
AttachDirection.X = Dir.X; AttachDirection.Y = Dir.Y;       // this+0x90c
AttachDirection.Z = Dir.Z;                                  // this+0x914
AttachOffset.X = Closest.X - TargetLoc.X;                   // this+0x900
AttachOffset.Y = Closest.Y - TargetLoc.Y;                   // this+0x904
AttachOffset.Z = Closest.Z - TargetLoc.Z;                   // this+0x908
NarrowPlacementAgainstVelocityThreshold_Stored = NarrowPlacementAgainstVelocityThreshold;   // this+0x918
StickyOffsetFromBoneCenter_Stored = StickyOffsetFromBoneCenter;                             // this+0x920
StickyOffsetFromPhysicsMesh_Stored = StickyOffsetFromPhysicsMesh;                           // this+0x91c

// Degenerate offset guard: when all three components are within 1e-4 of zero, X is set to 0.01f.
if (FMath::Abs(AttachOffset.X) <= 1e-4f && FMath::Abs(AttachOffset.Y) <= 1e-4f && FMath::Abs(AttachOffset.Z) <= 1e-4f)
{
    AttachOffset.X = 0.01f;                                 // 0x3c23d70a
}

OnAttachedToActor();                                        // vtable slot 0x6e8 -> 0x1426d5640 (RESIDUAL, ~6 KB body, not ported)
